import Foundation
import Security
import SwiftUI

// Master Logger for localization logging
private let logger = MasterLogger.shared

/**
 * 🌍 Localization Manager
 * Управление локализацией приложения
 * Поддержка RU + EN
 */

class LocalizationManager: ObservableObject {
    
    // MARK: - Singleton
    
    /// ✅ BUILD 112: Единый экземпляр для всего приложения
    /// Предотвращает многократную инициализацию тяжелого словаря переводов (9000+ строк)
    /// Это устраняет причину переполнения стека (excessive recursion) при старте.
    static let shared = LocalizationManager()
    
    // MARK: - Published Properties

    @Published var currentLanguage: Language = .russian

    /// ✅ НОВОЕ: Состояние готовности для предотвращения race conditions
    @Published var isReady: Bool = false

    /// Принудительный язык (для режима съёмки скриншотов)
    static var forcedLanguage: Language?
    
    // MARK: - Supported Languages
    
    enum Language: String, CaseIterable {
        case russian = "ru"
        case english = "en"
        case chinese = "zh-Hans"
        case arabic = "ar"

        /// Языки, доступные пользователю в онбординге и в переключателе приложения (только RU / EN).
        static var userSelectableLanguages: [Language] { [.russian, .english] }
        
        var displayName: String {
            switch self {
            case .russian: return "Русский"
            case .english: return "English"
            case .chinese: return "中文"
            case .arabic: return "العربية"
            }
        }
        
        var flag: String {
            switch self {
            case .russian: return "🇷🇺"
            case .english: return "🇬🇧"
            case .chinese: return "🇨🇳"
            case .arabic: return "🇦🇪"
            }
        }
        
        var isRTL: Bool {
            switch self {
            case .arabic: return true
            default: return false
            }
        }
    }
    
    // MARK: - Init
    
    init() {
        LaunchDiagnostics.appendStartupTrace("LocalizationManager.init BEGIN")
        // ✅ BUILD 115: Убрано логирование из init() для "Тихого старта"
        // ✅ СНАЧАЛА проверяем сохранённый язык
        if let savedLanguage = UserDefaults.standard.string(forKey: AppConfig.UserDefaultsKeys.appLanguage),
           let language = Language(rawValue: savedLanguage) {
            currentLanguage = language
        } else if let systemLanguage = Locale.current.languageCode,
                  let language = detectLanguage(from: systemLanguage) {
            // Если сохранённого нет, используем системный (с поддержкой префиксов)
            currentLanguage = language
        } else {
            // По умолчанию русский
            currentLanguage = .russian
        }

        normalizeDiscontinuedUserFacingLanguages()

#if DEBUG
        // ✅ BUILD 115: LocalizationDiagnostics.runInitialChecks перенесен в ALADDINApp.onAppear
#endif

        // ✅ НОВОЕ: Отмечаем готовность после полной инициализации
        // Небольшая задержка чтобы дать время на установку currentLanguage
        LaunchDiagnostics.appendStartupTrace("LocalizationManager.init END (before async isReady)")
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { [weak self] in
            self?.isReady = true
            print("✅ LocalizationManager: Ready for use")
        }
    }
    
    // MARK: - Language Detection

    /**
     * Определить язык по коду (с поддержкой префиксов)
     * Например: "en-US" -> .english, "zh-CN" -> .chinese
     */
    private func detectLanguage(from languageCode: String) -> Language? {
        // Сначала пробуем точное совпадение
        if let exactMatch = Language(rawValue: languageCode) {
            return exactMatch
        }

        // Если не нашли, пробуем по префиксу (для случаев "en-US", "zh-CN" и т.д.)
        let prefix = languageCode.prefix(2).lowercased()
        switch prefix {
        case "en":
            return .english
        case "ru":
            return .russian
        case "zh", "ar":
            return nil
        default:
            return nil
        }
    }

    /// Китайский и арабский убраны из выбора в приложении; сохранённые значения переводим на английский.
    private func normalizeDiscontinuedUserFacingLanguages() {
        guard currentLanguage == .chinese || currentLanguage == .arabic else { return }
        currentLanguage = .english
        UserDefaults.standard.set(Language.english.rawValue, forKey: AppConfig.UserDefaultsKeys.appLanguage)
        UserDefaults.standard.synchronize()
    }

    // MARK: - Change Language

    /**
     * Сменить язык приложения
     */
    func changeLanguage(to language: Language) {
        let resolved = Language.userSelectableLanguages.contains(language) ? language : .english
        logger.business("Changing application language to: \(resolved.rawValue)")
        // ✅ Обновляем текущий язык (это обновит UI через @Published)
        currentLanguage = resolved
        
        // Язык UI — некритичные prefs, остаётся в UserDefaults (не секрет).
        UserDefaults.standard.set(resolved.rawValue, forKey: AppConfig.UserDefaultsKeys.appLanguage)
        
        // Синхронизируем с системой
        UserDefaults.standard.synchronize()
        
        print("✅ Language changed to: \(resolved.displayName)")
    }
    
    /**
     * Получить Locale для применения в приложении
     */
    var locale: Locale {
        Locale(identifier: currentLanguage.rawValue)
    }

    /// Код языка ответа AI (REST и SSE), согласован с `ChatMessageRequest.response_language`.
    var aiResponseLanguageCode: String {
        switch currentLanguage {
        case .russian: return "ru"
        case .english: return "en"
        case .chinese: return "zh"
        case .arabic: return "ar"
        }
    }

    /// Локаль для `SFSpeechRecognizer` (BCP 47).
    var speechRecognitionLocale: Locale {
        switch currentLanguage {
        case .russian: return Locale(identifier: "ru-RU")
        case .english: return Locale(identifier: "en-US")
        case .chinese: return Locale(identifier: "zh-Hans")
        case .arabic: return Locale(identifier: "ar-SA")
        }
    }
    
